import{_ as i,l as n,o as e,c as o,v as t,p as s,x as l,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"拒绝训练与边界","description":"","frontmatter":{"title":"拒绝训练与边界","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/refusal-training.md","filePath":"llm/refusal-training.md","lastUpdated":1789023840000}'),h={name:"llm/refusal-training.md"};function c(m,a,A,u,T,B){const r=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="拒绝训练与边界" tabindex="-1">拒绝训练与边界 <a class="header-anchor" href="#拒绝训练与边界" aria-label="Permalink to &quot;拒绝训练与边界&quot;">​</a></h1><div class="epigraph"><p>安全 RM 把拒答当高分时，模型会把边界扩到 innocuous 请求；过拒绝与漏拒绝要成对报告。</p><footer>—— 对照 Llama 2 安全奖励；Bianchi 等 Safety-Tuned LLaMAs；XSTest / 过拒绝基准</footer></div><p><a href="/llm/constitutional-rl-practice">上一课</a>用原则定义无害。落到行为上，最硬的动作是拒绝。缺口是：<strong>拒绝是可优化的，默认会扩大；边界必须用正例与反例一起训。</strong> 本课写拒绝训练，不提供越狱步骤，只写评测与数据协议。接到诚实课：拒答不是撒谎，但「我不知道」与「我不能说」要分开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/rlhf-pipeline">RLHF</a> 的安全比较里，拒答常常赢。PPO 于是提高拒答先验。Bianchi 等人显示：少量安全 SFT 就能让模型对无害题也拒。XSTest 一类基准专门测过度拒绝（把「如何杀死进程」当暴力）。漏拒绝是另一头：红队仍能找到配合。只报有害提示拒答率，是半张表。</p><p>边界依赖意图与语境，不是关键词。细则里「协助犯罪=拒、虚构写作=允」必须有成对数据，否则 RM 走捷径。</p><h3 id="拒绝格式也是策略" tabindex="-1">拒绝格式也是策略 <a class="header-anchor" href="#拒绝格式也是策略" aria-label="Permalink to &quot;拒绝格式也是策略&quot;">​</a></h3><p>长篇道德训诫、短拒、转移话题，安全 RM 可能都给高分。产品要短拒 + 解释可允许的替代。把格式写进细则或硬规则，不要指望标量 RM 自己长出。宪法条款应写「最小充分拒绝」。</p><p><span class="marginnote">不要用越狱成功率当唯一 KPI。它随提示分布漂移，且与过拒绝负相关。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据：有害请求 → 合格拒绝；看起来敏感实则无害 → 必须回答；边界题双标（专家）。训练：SFT 先锁格式，再安全 RM + 有用 RM 硬门（<a href="/llm/multi-objective-reward">多目标</a>）。评测：有害集拒答率、XSTest 一类允答率、有用 Arena。RL 阶段对过拒绝给负奖励，需金标，不能让安全 RM 自己标——它正是过拒绝的来源。</p>',11)),(e(),s(E,null,{default:l(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20HARM%5B%22%E6%9C%89%E5%AE%B3%E6%8F%90%E7%A4%BA%22%5D%20--%3E%20REF%5B%22%E5%90%88%E6%A0%BC%E6%8B%92%E7%BB%9D%22%5D%0A%20%20BEN%5B%22%E6%97%A0%E5%AE%B3%E6%98%93%E8%AF%AF%E6%8B%92%22%5D%20--%3E%20ANS%5B%22%E5%BF%85%E9%A1%BB%E4%BD%9C%E7%AD%94%22%5D%0A%20%20REF%20--%3E%20SFT%5B%22SFT%20%2B%20%E5%AE%89%E5%85%A8%20RM%22%5D%0A%20%20ANS%20--%3E%20SFT%0A%20%20SFT%20--%3E%20RL%5B%22PPO%20%E7%A1%AC%E9%97%A8%22%5D%0A%20%20RL%20--%3E%20MET%5B%22%E6%8B%92%E7%AD%94%E7%8E%87%20%E2%88%A9%20%E8%BF%87%E6%8B%92%E7%BB%9D%E7%8E%87%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 <a href="/llm/dpo">DPO</a> ：用「拒 vs 配合」对直接推边界，β 过大会回到 SFT 的过拒或过配，取决于 SFT 偏向哪边。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>拒答是短轨迹、高安全分、低有用分。硬门不对称时，梯度稳定推向拒。过拒绝是这条几何的默认终点，要用无害正例的正优势对冲。模型规模越大，越会从预训练里找回配合能力，安全 SFT 更像浅层开关——泛化到改写提示时开关失效。这是红队持续存在的原因，不是一次 RL 能封死。</p><p><span class="marginnote">可验证域很少需要拒答（题就是题）。本课主场是开放助手。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>法律与医疗的「拒 vs 给一般信息」各国不同，数据合同要地域化。下一课诚实：该答但不确定时，应校准而不是拒；把不知道当成安全拒，会伤害有用并教撒谎式推诿。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>拒绝可被 PPO 扩大；必须同时训无害正例并报过拒绝。</li><li>安全 RM 不能当过拒绝的金标。</li><li>拒绝格式写进细则：最小充分拒绝。</li><li>边界是语境而不是关键词，需要专家双标。</li><li>出处：Touvron 等 Llama 2；Bianchi 等 Safety-Tuned LLaMAs；XSTest 过拒绝评测。</li></ul>',8))])}const S=i(h,[["render",c]]);export{f as __pageData,S as default};
